def merge_duplicate_open_alerts(apps, schema_editor):
    """Keep the latest unresolved record for each key and preserve older history."""
    alerts = apps.get_model('monitor', 'AlertLog').objects.using(schema_editor.connection.alias)
    unresolved = alerts.filter(status__in=('active', 'acknowledged'))
    duplicate_keys = (unresolved.order_by().values('config_id', 'alert_type', 'metric_key')
                      .annotate(total=models.Count('id')).filter(total__gt=1))
    for key in duplicate_keys.iterator(chunk_size=500):
        key.pop('total')
        group = unresolved.filter(**key).order_by('-create_time', '-pk')
        ids = list(group.values_list('pk', flat=True))
        if len(ids) > 1:
            alerts.filter(pk__in=ids[1:]).update(
                status='superseded',
                recovery_evidence={'source': 'history_merge', 'retained_alert_id': ids[0]},
            )


